// New Base Classes (15 splatbook classes) — added from the "D&D 3.5 Edition Index – Base Classes"
// fan compendium (crystalkeep.com/d20, compiled by Chet Erez). Mechanical reference data only —
// no reproduced copyrighted class-feature prose. Progression tables use standard SRD BAB/save
// formulas (full/three-quarter/half BAB; good-save 2+level/2, poor-save level/3, rounded per the
// SRD tables), capped at level 10 to match this app's per-class level cap.
import type { ClassDefinition, FeatureDefinition } from "../../engine/types";

type F = FeatureDefinition & { levelsNeeded?: number };

function f(
  name: string,
  description: string,
  levelsNeeded: number | undefined,
  source: string,
  sourceUrl: string,
): F {
  return {
    key: name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, ""),
    name,
    description,
    category: "special-quality",
    source,
    sourceUrl,
    ...(levelsNeeded ? { levelsNeeded } : {}),
  };
}

